<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { api } from '../api'
import { useSession, type Profile } from '../session'
interface Doctor { id: string; displayName: string; title: string; biography: string; credentialStatus: string; enabled: boolean; departmentId: string | null; departmentName: string | null }
interface Home { activeAppointmentId: string | null }
const router = useRouter(), session = useSession(), profile = ref<Profile | null>(null), doctor = ref<Doctor | null>(null), home = ref<Home | null>(null), loading = ref(true), error = ref('')
const displayName = computed(() => doctor.value?.displayName || profile.value?.displayName || profile.value?.identifier || '医生')
const credentialLabel = computed(() => doctor.value?.credentialStatus === 'CERTIFIED' ? '已认证' : doctor.value?.credentialStatus === 'REJECTED' ? '已驳回' : '待审核')
const maskedPhone = computed(() => { const value = profile.value?.phoneNumber; return value && value.length >= 7 ? `${value.slice(0, 3)}****${value.slice(-4)}` : '未提供' })
async function load() { loading.value = true; error.value = ''; try { [profile.value, doctor.value, home.value] = await Promise.all([api<Profile>('/profile'), api<Doctor>('/doctor/catalog/profile'), api<Home>('/doctor/home')]) } catch (failure) { error.value = failure instanceof Error ? failure.message : '个人资料暂时无法加载，请重试' } finally { loading.value = false } }
async function logout() { const message = home.value?.activeAppointmentId ? '当前仍有未结束接诊，退出后不会结束接诊或丢失草稿。确认退出登录？' : '确认退出登录？'; if (!window.confirm(message)) return; try { await session.logout(); await router.push('/login') } catch (failure) { error.value = failure instanceof Error ? failure.message : '退出登录失败，请重试' } }
onMounted(load)
</script>
<template>
  <section class="doctor-profile" aria-labelledby="doctor-profile-title"><div v-if="loading" class="doctor-profile-state" role="status">正在加载个人资料…</div><div v-else-if="error" class="doctor-profile-state" role="alert"><p>{{ error }}</p><button type="button" @click="load">重试加载</button></div><template v-else><header><p class="eyebrow">ACCOUNT & CREDENTIALS</p><h1 id="doctor-profile-title">个人资料</h1><p>资料来自本人账户、医生认证和科室归属，只读展示。</p></header><div class="doctor-profile-grid"><section class="card doctor-profile-card" aria-label="医生资料"><div class="doctor-avatar">{{ displayName.slice(0, 1) }}</div><h2>{{ displayName }}</h2><p>{{ doctor?.title || '医生' }} · {{ doctor?.departmentName || '尚未分配科室' }}</p><span class="credential-badge">{{ credentialLabel }}</span><dl><div><dt>登录账号</dt><dd>{{ profile?.identifier }}</dd></div><div><dt>联系电话</dt><dd>{{ maskedPhone }}</dd></div><div><dt>医生编号</dt><dd>{{ doctor?.id || profile?.id }}</dd></div></dl></section><section class="card doctor-account-card" aria-label="账户与设置"><h2>账户与设置</h2><div class="account-row"><span>认证状态</span><strong>{{ credentialLabel }}</strong></div><div class="account-row"><span>接诊状态</span><strong>{{ home?.activeAppointmentId ? '接诊中' : '当前无接诊' }}</strong></div><p class="hint">资料编辑、改密和短信验证暂未开放；本页面不会伪造保存成功。</p><button type="button" class="logout-button" @click="logout">退出登录</button></section></div></template></section>
</template>
<style scoped>
.doctor-profile { display: grid; gap: 18px; }.doctor-profile header h1 { margin: 0 0 8px; }.doctor-profile header > p:not(.eyebrow) { margin: 0; color: #64748b; }.doctor-profile-grid { display: grid; grid-template-columns: minmax(260px, .8fr) minmax(320px, 1.2fr); gap: 18px; }.doctor-profile-card, .doctor-account-card { padding: 24px; }.doctor-profile-card { text-align: center; }.doctor-avatar { display: grid; place-items: center; width: 72px; height: 72px; margin: 0 auto 14px; border-radius: 50%; color: #fff; background: #2563eb; font-size: 2rem; font-weight: 700; }.doctor-profile-card h2, .doctor-account-card h2 { margin: 0 0 8px; }.doctor-profile-card > p { margin: 0 0 12px; color: #64748b; }.credential-badge { display: inline-block; padding: 5px 10px; border-radius: 999px; color: #1d4ed8; background: #dbeafe; font-size: .85rem; font-weight: 700; }.doctor-profile-card dl { display: grid; gap: 12px; margin: 24px 0 0; text-align: left; }.doctor-profile-card dl div { display: flex; justify-content: space-between; gap: 14px; padding-top: 12px; border-top: 1px solid #e5e7eb; }.doctor-profile-card dt { color: #64748b; }.doctor-profile-card dd { margin: 0; color: #1f2937; text-align: right; overflow-wrap: anywhere; }.doctor-account-card { display: grid; align-content: start; gap: 14px; }.account-row { display: flex; justify-content: space-between; gap: 12px; padding: 14px 0; border-bottom: 1px solid #e5e7eb; }.account-row span, .hint { color: #64748b; }.account-row strong { color: #1d4ed8; }.hint { line-height: 1.6; }.logout-button, .doctor-profile-state button { width: fit-content; border: 0; border-radius: 8px; padding: 10px 16px; color: #fff; background: #b42318; cursor: pointer; font-weight: 700; }.doctor-profile-state { padding: 40px 20px; border-radius: 12px; background: #fff; text-align: center; }.doctor-profile-state p { color: #b42318; }.doctor-profile-state button { color: #1d4ed8; background: #eff6ff; }
@media (max-width: 700px) { .doctor-profile-grid { grid-template-columns: 1fr; } }
</style>

